def is_segment_ready_nominal(gamma, current_time, S_nominal):
    if gamma.remaining_workload_nominal > 0 and current_time >= gamma.r_nominal:
        return True
    return False

def calculate_nominal_segment_release_time(job_J, segment_gamma, S_nominal):
    if segment_gamma.is_first_segment_of_job:
        segment_gamma.r_nominal = job_J.r
    else:
        prev_segment = get_previous_segment(segment_gamma)
        segment_gamma.r_nominal = prev_segment.f_nominal + prev_segment.S_max_suspension

def is_segment_ready_online(gamma, current_time, S_online):
    if gamma.remaining_workload_online > 0 and current_time >= gamma.r_online:
        return True
    return False

def calculate_online_segment_release_time(job_J, segment_gamma, S_online):
    if segment_gamma.is_first_segment_of_job:
        segment_gamma.r_online = job_J.r
    else:
        prev_segment = get_previous_segment(segment_gamma)
        segment_gamma.r_online = prev_segment.f_online + prev_segment.S_max_suspension

def calculate_enforced_segment_release_time(job_J, segment_gamma, S_online, S_nominal):
    if segment_gamma.is_first_segment_of_job:
        segment_gamma.r_enf = job_J.r
    else:
        prev_segment = get_previous_segment(segment_gamma)
        natural_online_release = prev_segment.f_online + prev_segment.S_max_suspension
        segment_gamma.r_enf = max(natural_online_release, segment_gamma.r_nominal)
